/// The extension IEs of `PLMNSupportItem-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PlmnSupportItemExtIes {
    /// `id-NPN-Support` (id 258, Reject, Optional)
    pub npn_support: Option<NpnSupport>,
    /// `id-ExtendedSliceSupportList` (id 270, Reject, Optional)
    pub extended_slice_support_list: Option<ExtendedSliceSupportList>,
    /// `id-OnboardingSupport` (id 325, Ignore, Optional)
    pub onboarding_support: Option<OnboardingSupport>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl PlmnSupportItemExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            npn_support: None,
            extended_slice_support_list: None,
            onboarding_support: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for PlmnSupportItemExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.npn_support {
            ies.push(rt::ie::RawIe::new(258, rt::ie::Criticality::Reject, x)?);
        }
        if let Some(x) = &self.extended_slice_support_list {
            ies.push(rt::ie::RawIe::new(270, rt::ie::Criticality::Reject, x)?);
        }
        if let Some(x) = &self.onboarding_support {
            ies.push(rt::ie::RawIe::new(325, rt::ie::Criticality::Ignore, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for PlmnSupportItemExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_npn_support: Option<NpnSupport> = None;
        let mut s_extended_slice_support_list: Option<ExtendedSliceSupportList> = None;
        let mut s_onboarding_support: Option<OnboardingSupport> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                258 => rt::ie::set_once(&mut s_npn_support, 258, ie.decode()?)?,
                270 => rt::ie::set_once(&mut s_extended_slice_support_list, 270, ie.decode()?)?,
                325 => rt::ie::set_once(&mut s_onboarding_support, 325, ie.decode()?)?,
                _ => unknown_ies.push(ie),
            }
        }
        Ok(Self {
            npn_support: s_npn_support,
            extended_slice_support_list: s_extended_slice_support_list,
            onboarding_support: s_onboarding_support,
            unknown_ies,
        })
    }
}

